<template>
  <div class="page"><div class="head"><div><h1>往来核销</h1><p>选择已确认且仍有未核销余额的资金单进入核销。</p></div></div><section class="filter"><el-radio-group v-model="direction" @change="search"><el-radio-button label="receipt">客户收款</el-radio-button><el-radio-button label="payment">供应商付款</el-radio-button></el-radio-group><el-input v-model.trim="keyword" clearable placeholder="资金单号 / 交易对手" @keyup.enter.native="search" /><el-button type="success" @click="search">查询</el-button><el-button @click="keyword='';search()">重置</el-button></section><section class="table"><el-table v-loading="loading" :data="rows" border size="small"><el-table-column prop="document_no" label="资金单号" min-width="170" /><el-table-column label="业务日期" width="115"><template slot-scope="{row}">{{dateText(row.business_date)}}</template></el-table-column><el-table-column prop="party_name_snapshot" label="交易对手" min-width="170" /><el-table-column label="资金金额" width="130" align="right"><template slot-scope="{row}">{{money(row.amount)}}</template></el-table-column><el-table-column label="已核销" width="120" align="right"><template slot-scope="{row}">{{money(row.allocated_amount)}}</template></el-table-column><el-table-column label="未核销" width="120" align="right"><template slot-scope="{row}"><b class="orange">{{money(row.unallocated_amount)}}</b></template></el-table-column><el-table-column label="操作" width="100"><template slot-scope="{row}"><el-button v-if="Number(row.unallocated_amount)>0" type="text" @click="$router.push({path:`/finance/allocations/${row.id}`,query:{from:'allocation-list'}})">进入核销</el-button><span v-else>已完成</span></template></el-table-column></el-table><el-pagination background layout="total, sizes, prev, pager, next, jumper" :current-page="page" :page-size="perPage" :page-sizes="[10,20,50,100]" :total="total" @current-change="p=>{page=p;load()}" @size-change="s=>{perPage=s;page=1;load()}" /></section></div>
</template>
<script>
import {listCashDocuments} from '../../../api/erp/finance'
export default {data:()=>({direction:'receipt',keyword:'',rows:[],loading:false,page:1,perPage:20,total:0}),created(){this.load()},methods:{money(v){return Number(v||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:4})},dateText(v){return String(v||'').replace('T',' ').slice(0,10)||'—'},search(){this.page=1;this.load()},async load(){this.loading=true;try{const r=await listCashDocuments(this.direction,{keyword:this.keyword,status:'confirmed',page:this.page,per_page:this.perPage});this.rows=r.data.data||[];this.total=Number(r.data.total||0)}catch(e){this.$message.error(e.userMessage||'待核销资金单加载失败')}finally{this.loading=false}}}}
</script>
<style scoped>.page{padding:20px;min-width:0}.head{display:flex;justify-content:space-between;margin-bottom:16px}.head h1{font-size:24px;margin:0 0 6px}.head p{margin:0;color:#7b8794}.filter,.table{background:#fff;border:1px solid #e3e8ef;border-radius:6px;padding:16px;margin-bottom:14px}.filter{display:grid;grid-template-columns:auto minmax(250px,1fr) auto auto;gap:12px}.table{overflow:hidden}.el-pagination{text-align:right;margin-top:16px}.orange{color:#f79009}@media(max-width:780px){.filter{grid-template-columns:1fr 1fr}.table{overflow-x:auto}}</style>
